import re
import string
from six.moves.urllib.request import urlopen

from taf.hw.rf_switch.devices.rf_switch import RfSwitch
from taf.hw.rf_switch.exceptions import SetPortStatusFailure, RfSwitchActionNotSupported, GetPortStatusfailure


class MiniCircuits(RfSwitch):
    """Base class for Mini-Circuits RF switches connection support.
    Mini-Circuit switches have a little different structure than other RF switches. It contains up to
    8 separate switches which are named from "A" to "H". In this class, each switch is treated
    like separate port_in value, which can be connected to port_out ports.

    :param ip: Ip address of Rf Switch.
    :param port: Port of Rf Switch. Defaults to 80.
    :param password: Password used to secured login. Defaults to None.
    """

    _switch_name_cmd = None  # type: str
    _set_cmd = "STATE:{state}"
    _get_cmd = "STATE?"
    _get_model_cmd = "MN?"
    _number_of_switches_regex = r"\-(\d){type}\-"

    def __init__(self, ip, port=80, password=None):
        super().__init__()
        self._url = f"http://{ip}:{port}/"
        if password:
            self._url = f"{self._url}PWD={password};"

    def __new__(cls, *args, **kwargs):
        if cls is MiniCircuits:
            raise TypeError("Instantiation of base MiniCircuit class is prohibited!")
        return object.__new__(cls)

    def _send_command(self, cmd):
        """Send command via urlopen to Rf Switch.

        :param cmd: Command that should be sent.
        :return: Response from RF switch converted to string value.
        """
        response = urlopen(f"{self._url}{cmd}").read()
        return response.decode("utf-8")

    def _prepare_set_cmd(self, port_in, port_out):
        """Method that prepares SET command.

        :param port_in: Rf Switch port that should be connected.
        :param port_out: Rf Switch ID.
        :return: SET command ready to be sent to Rf Switch.
        """
        return "{switch}{set_cmd}".format(
            switch=self._switch_name_cmd.format(switch=port_out),
            set_cmd=self._set_cmd.format(
                state=port_in,
            ),
        )

    def _prepare_get_cmd(self, port_out):
        """Method that prepares GET command.

        :param port_out: Rf Switch ID.
        :return: GET command ready to be sent to Rf Switch.
        """
        return f"{self._switch_name_cmd.format(switch=port_out)}{self._get_cmd}"

    def _get_all_switches_list(self):
        """Method that gets list of all switches available on device.

        :return: String value containing alphabetical sequence of Rf Switches.
        """
        model = self._send_command(self._get_model_cmd)
        pattern = re.compile(self._number_of_switches_regex.format(type=self.__class__.__name__))
        number_of_switches = int(pattern.search(model).group(1))
        return string.ascii_uppercase[0:number_of_switches]

    def connect_ports(self, port_in, port_out):
        """Method responsible for connecting ports on Rf Switch. If command fails, it raises exception.

        :param port_in: Rf Switch port that should be connected.
        :param port_out: Rf Switch ID. String value from "A" up to "H".
        :raises SetPortStatusFailure: When response is not equal to 1
        """
        response = self._send_command(self._prepare_set_cmd(port_in, port_out))
        if response != "1":
            raise SetPortStatusFailure(
                f"Could not connect to {port_in} port on {port_out} switch."
            )

    def disconnect_ports(self, _, port_out="A"):
        """Method responsible for disconnecting port on Rf Switch. If command fails, it raises exception.

        :param port_out: Rf Switch ID.
        :raises SetPortStatusFailure: When response is not equal to 1
        """
        response = self._send_command(self._prepare_set_cmd(0, port_out))
        if response != "1":
            raise SetPortStatusFailure(f"Could not disconnect ports on {port_out} switch!")

    def get_port_in_status(self, *_, **__):
        """Command responsible for getting port_in status. Not supported by current Mini-Circuit switches."""
        raise RfSwitchActionNotSupported("Mini-circuits RF switches support only port out status check.")

    def get_port_out_status(self, port_out):
        """Command responsible for getting status of port connected to specified switch on the device.

        :param port_out: Rf Switch ID.
        :return: Status of port connected to specified switch.
        """
        return self._send_command(self._prepare_get_cmd(port_out))

    def get_connected_ports(self):
        """Command responsible for getting statuses of all ports on the device.

        For mini-circuits devices, get_connected_ports returns different dictionary structure, than for other switches:
            - keys are the port_out values instead of port_in
            - values are the port_in values instead of port_out
        This is caused due to the device specific - it can contain multiple switches, which are mapped by port_out.
        Each switch has same port_in value ranges, so the key's wouldn't be unique in for the standard dict structure.

        :return: Dict object containing mapping of all ports connected to all switches.
        """
        return {switch: self.get_port_out_status(switch) for switch in self._get_all_switches_list()}


class SP6T(MiniCircuits):
    """Class for all SP6T switches."""

    _switch_name_cmd = "SP6T{switch}:"


class SP4T(MiniCircuits):
    """Class for all SP4T switches."""

    _switch_name_cmd = "SP4T{switch}:"


class SPDT(MiniCircuits):
    """Class for all SPDT switches."""

    _set_cmd = "SET{switch}={state}"
    _get_cmd = "SWPORT?"
    _max_switch_combination = "HGFEDCBA"

    def _prepare_set_cmd(self, port_in, port_out):
        """Method preparing SET command for SPDT switch.

        :param port_in: Rf Switch port that should be connected.
        :param port_out: Rf Switch ID.
        :return: SET command ready to be sent to Rf Switch.
        """
        return self._set_cmd.format(switch=port_out, state=port_in)

    def _prepare_get_cmd(self, *_):
        """Method that prepares GET command.

        :return: GET command ready to be sent to SPDT Switch.
        """
        return self._get_cmd

    def disconnect_ports(self, *_, **__):
        """Method responsible for disconnecting port on Rf Switch. Not supported in SPDT switches."""
        raise RfSwitchActionNotSupported("Cannot disconnect ports on SPDT switch!")

    def get_port_out_status(self, port_out):
        """Command responsible for getting status of port connected to specified switch on the device.

        :param port_out: Rf Switch ID.
        :raises GetPortStatusfailure: If invalid switch is selected.
        :return: Status of port connected to specified switch.
        """
        result = self.get_connected_ports().get(port_out, None)
        if result:
            return result
        raise GetPortStatusfailure(f"Port {port_out} not available!")

    def get_connected_ports(self):
        """Command responsible for getting statuses of all ports on the device.

        :return: Dict object containing mapping of all ports connected to all switches.
        """
        response = int(self._send_command(self._prepare_get_cmd()))
        ports = self._get_all_switches_list()
        return {
            switch: state
            for switch, state in dict(zip(self._max_switch_combination, f"{response:08b}")).items()
            if switch in ports
        }
